import{_ as a,o,c as s,a0 as t}from"./chunks/framework.BLL-IG04.js";const m=JSON.parse('{"title":"The release model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/release-model.md","filePath":"explanation/release-model.md"}'),r={name:"explanation/release-model.md"};function i(n,e,l,c,d,h){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="the-release-model" tabindex="-1">The release model <a class="header-anchor" href="#the-release-model" aria-label="Permalink to &quot;The release model&quot;">​</a></h1><p>mimus releases itself — there is no hosted CI and no release tool in the loop. Releases are manual: <code>scripts/release.sh</code> is run by an operator on <code>main</code>. The script&#39;s leading sleep is the debounce window — a newer push kills a running release via <code>cancel_running</code>, so only the last push in a quiet window releases.</p><p>The org release plane is <strong>tarsi</strong> (<code>tarsi-serve</code> ops — project ADR-0005): <code>scripts/release.sh</code> is being converted to a thin shim over it (PL-014 E1), and until then this script implements the same tag-only model directly.</p><p><strong>No crates.io publish</strong>: org policy keeps every repo but tamias off crates.io, and the mimus crates are internal lib-only engines behind <code>tamias-driver-mimus</code>. There is no tamias pack yet either — installs stay <code>cargo install --git https://github.com/9aia/mimus mimus</code>, pinning a rev or a tag.</p><h2 id="what-a-release-run-does" tabindex="-1">What a release run does <a class="header-anchor" href="#what-a-release-run-does" aria-label="Permalink to &quot;What a release run does&quot;">​</a></h2><ol><li><strong>Diff since the last tag</strong> — release-worthy paths are the workspace crates (<code>crates/</code>), the example manifest compiled into the CLI (<code>examples/</code> is <code>include_str!</code>-ed), and the release machinery itself. Changes to anything else trigger nothing. No release-set changes, no release.</li><li><strong>Workspace version bump</strong> — every crate inherits <code>version.workspace</code>, so <code>cargo set-version --workspace --bump patch</code> moves them all at once and rewrites the <code>workspace.dependencies</code> version reqs and <code>Cargo.lock</code> together.</li><li><strong>Docs regen</strong> — <code>docs/</code> is a separate worktree (orphan <code>docs</code> branch); when present, the script regenerates <code>docs/reference/cli.md</code> and the config reference so they match the released CLI.</li><li><strong>Commit + tag + push</strong> — one <code>release: bump mimus to &lt;ver&gt;</code> commit, tagged <code>mimus-v&lt;ver&gt;</code>, pushed to <code>main</code> with the tag.</li></ol><p>With no tags at all the script exits early — the flow is seeded by tagging once.</p><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><ul><li>There is no crates.io publish path and no per-crate tag scheme — the whole workspace shares one version and one <code>mimus-v&lt;ver&gt;</code> tag. The old push-driven <code>mimus deploy release</code> seed (which <code>cargo publish</code>ed every member and uploaded cargo-dist binaries to a GitHub Release) is retired: org policy keeps every repo but tamias off crates.io, and prebuilt binary distribution is not part of the flow.</li><li>Install is <code>cargo install --git</code> until a tamias pack exists — a <code>libraries/mimus</code> pack (mirroring kuda&#39;s <code>bins[]</code> shim over <code>tamias-driver-mimus</code>) is the planned distribution path.</li></ul>',9)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
